#!/usr/bin/env node
// Exact AVHL V7 futures pipeline: 780 unordered team pairs, 50 games with
// each team at home, cached until V7 engine or either lineup changes.
// Every score is generated by the deployed V7 simulator, never a surrogate.
import fs from "node:fs/promises";
import vm from "node:vm";
import {createHash} from "node:crypto";
import process from "node:process";
import {teams} from "../data/teams.js";
import {buildProjectedLineup} from "../src/lib/lineups.js";
import {recordFromProjected} from "../src/lib/lineupRecords.js";
import {makeAllPairEntries,snapshotDigest,canonicalPairKey,validatePairPool,sha16} from "../src/lib/v7FuturesPairs.js";

const args=process.argv.slice(2);
const arg=(key,def="")=>{const i=args.indexOf(key);return i<0?def:args[i+1]||def;};
const mode=arg("--mode");
const fixture=args.includes("--fixture");
const root=(process.env.AVHL_ODDS_SITE_URL||"https://www.avhl.org").replace(/\/+$/,"");
if(!["plan","shard","finalize","smoke"].includes(mode))throw Error("--mode must be plan, shard, finalize or smoke.");
if(fixture&&mode!=="smoke")throw Error("Fixture/demo lineups cannot be published as AVHL odds.");
const controlUrl="https://www.avhl.org/api/odds/v7-futures-control";
const files=["public/sim/team-metadata.js","public/sim/data.js","public/sim/simulator.js"];
const source=await Promise.all(files.map(p=>fs.readFile(p,"utf8")));
const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function retry(fn,label,attempts=3){
 let error;
 for(let n=1;n<=attempts;n++){
   try{return await fn();}catch(e){error=e;if(n<attempts){
     console.warn(label+" attempt "+n+" failed; retrying.");
     await pause(n*10000);
   }}
 }
 throw Error(label+" failed after "+attempts+" attempts: "+String(error));
}
async function signedToken(){
 const url=process.env.ACTIONS_ID_TOKEN_REQUEST_URL;
 const key=process.env.ACTIONS_ID_TOKEN_REQUEST_TOKEN;
 if(!url||!key)throw Error("Signed GitHub Actions workload identity is unavailable.");
 const target=url+(url.includes("?")?"&":"?")+"audience="+encodeURIComponent(controlUrl.replace("www.",""));
 const response=await fetch(target,{
   headers:{Authorization:"Bearer "+key},cache:"no-store",signal:AbortSignal.timeout(10000)
 });
 if(!response.ok)throw Error("GitHub did not provide an OIDC token.");
 const result=await response.json();
 if(typeof result.value!=="string")throw Error("GitHub returned an invalid workload token.");
 return result.value;
}
async function postControl(body){
 return retry(async()=>{
   const jwt=await signedToken();
   const response=await fetch(controlUrl,{
     method:"POST",cache:"no-store",signal:AbortSignal.timeout(120000),
     headers:{"Content-Type":"application/json",Authorization:"Bearer "+jwt},
     body:JSON.stringify(body)
   });
   const result=await response.json();
   if(!response.ok||!result?.ok)
     throw Error("Server control "+body.action+" HTTP "+response.status+": "+JSON.stringify(result));
   return result;
 },"V7 futures "+body.action,3);
}
async function liveRosters(){
 if(fixture){
   const {players}=await import("../data/players.js");
   return {
     ok:true,source:"live",players:players.filter(p=>p.currentTeam&&p.currentTeam!=="UFA"),
     lineups:Object.fromEntries(teams.map(team=>[team.abbreviation,
       recordFromProjected(team.abbreviation,buildProjectedLineup(
         players.filter(p=>p.currentTeam===team.name)))]))
   };
 }
 return retry(async()=>{
   const response=await fetch(root+"/api/sim-rosters",{
     cache:"no-store",signal:AbortSignal.timeout(60000)
   });
   if(!response.ok)throw Error("Official AVHL live roster endpoint returned "+response.status);
   const data=await response.json();
   if(!data?.ok||data.source!=="live"||!Array.isArray(data.players)||!data.lineups)
     throw Error("Live AVHL roster and owner lineups unavailable; refuse fallback.");
   return data;
 },"Read official AVHL live rosters",3);
}
async function liveEngine(){
 const roster=await liveRosters();
 const ctx={
   console,Date,Math,structuredClone,
   fetch:async u=>{
     if(String(u).startsWith("/api/sim-rosters"))
       return {ok:true,status:200,json:async()=>roster};
     throw Error("Unexpected simulator data endpoint "+u);
   }
 };
 ctx.self=ctx;ctx.window=ctx;ctx.globalThis=ctx;
 vm.createContext(ctx);
 source.forEach((text,i)=>vm.runInContext(text,ctx,{filename:files[i]}));
 await ctx.AVHL_LOAD_LIVE_ROSTERS();
 return {ctx,engine:source[2],roster};
}
function resultTuple(result,aHome){
 const a=aHome?result.homeScore:result.awayScore;
 const b=aHome?result.awayScore:result.homeScore;
 const sample=[Number(a),Number(b),result.finish==="REG"?0:1];
 if(!Number.isInteger(sample[0])||!Number.isInteger(sample[1])||
    sample[0]===sample[1])throw Error("V7 game returned an invalid final score.");
 return sample;
}
function seedFor(key,homeDesignation,index){
 const hex=createHash("sha256").update(key+":"+homeDesignation+":"+index).digest("hex");
 return Number.parseInt(hex.slice(0,8),16);
}
function sampleMatchup(ctx,match,key,homeIsA,count){
 const rows=[];
 for(let i=0;i<count;i++){
   const sim=new ctx.AVHLGameSimulator(structuredClone(match),
     seedFor(key,homeIsA?"A":"B",i),{headless:true});
   rows.push(resultTuple(sim.simulateScoreOnly(),homeIsA));
 }
 return rows;
}
async function main(){
 if(mode==="finalize"){
   const snapshot=arg("--snapshot");
   if(!/^[a-f0-9]{24}$/.test(snapshot))throw Error("Expected canonical snapshot digest.");
   const result=await postControl({action:"finalize",snapshot});
   console.log(JSON.stringify(result));return;
 }
 const {ctx,engine}=await liveEngine();
 const all=makeAllPairEntries(teams.map(t=>t.abbreviation),engine,
   (home,away)=>ctx.AVHL_CREATE_MATCHUP_DATA(home,away));
 const snapshot=snapshotDigest(all);
 if(mode==="smoke"){
   if(!fixture)throw Error("Smoke tests must use clearly labeled bundled fixture rosters.");
   const {a,b,key}=all.find(x=>x.a==="ARI"&&x.b==="ATL")||all[0];
   const first=ctx.AVHL_CREATE_MATCHUP_DATA(a,b);
   const second=ctx.AVHL_CREATE_MATCHUP_DATA(b,a);
   const count=Number(arg("--games","1"));
   if(!Number.isInteger(count)||count<1||count>50)throw Error("Smoke games must be 1–50 per orientation.");
   const left=sampleMatchup(ctx,first,key,true,count),right=sampleMatchup(ctx,second,key,false,count);
   const full=count===50?validatePairPool({firstHome:left,secondHome:right}):null;
   if(count===50&&!full)throw Error("Failed full V7 50/50 pairing smoke.");
   console.log(JSON.stringify({mode:"fixture-v7-game-smoke",first:a,second:b,
     scoreAHome:count===1?left:left.slice(0,3),scoreBHome:count===1?right:right.slice(0,3),
     perHomeGames:count,validFullPool:full,
     pairCount:all.length,digest:snapshot,engineHash:sha16(engine)}));
   return;
 }
 if(mode==="plan"){
   const result=await postControl({action:"inspect",snapshot,entries:all});
   const missing=result.missing||[];
   const shards=[];
   for(let i=0;i<missing.length;i+=10)shards.push({pairs:missing.slice(i,i+10)});
   const matrix={include:shards};
   if(process.env.GITHUB_OUTPUT)await fs.appendFile(process.env.GITHUB_OUTPUT,
     "snapshot="+snapshot+"\nmissing="+missing.length+"\nmatrix="+JSON.stringify(matrix)+"\n");
   console.log(JSON.stringify({mode,requestedPairs:all.length,alreadyReady:all.length-missing.length,
     missing:missing.length,shards:shards.length,snapshot}));
   return;
 }
 const requested=JSON.parse(process.env.V7_FUTURES_PAIRS_JSON||"null");
 const expected=arg("--snapshot");
 if(!Array.isArray(requested)||!requested.length||requested.length>10||
    expected!==snapshot)throw Error("Live V7 team lineup fingerprint changed since planning; retry at next 30-minute refresh.");
 for(const [i,p] of requested.entries()){
   const exact=all.find(e=>e.a===p.a&&e.b===p.b);
   if(!exact||exact.key!==p.key)throw Error("Requested pair no longer matches the exact V7 engine/lineups.");
   const matchA=ctx.AVHL_CREATE_MATCHUP_DATA(p.a,p.b);
   const matchB=ctx.AVHL_CREATE_MATCHUP_DATA(p.b,p.a);
   if(canonicalPairKey(p.a,p.b,engine,matchA,matchB)!==p.key)
     throw Error("Lineup mismatch: cannot publish stale V7 outcomes.");
   const pool={
     firstHome:sampleMatchup(ctx,matchA,p.key,true,50),
     secondHome:sampleMatchup(ctx,matchB,p.key,false,50)
   };
   if(!validatePairPool(pool))throw Error("Invalid genuine V7 50/50 sample pool.");
   await postControl({action:"ingest",snapshot,key:p.key,pool});
   console.log("Saved real V7 pair "+(i+1)+"/"+requested.length+": "+p.a+"–"+p.b+" (50/50)");
 }
 console.log(JSON.stringify({mode:"shard",completedPairs:requested.length,simulatedGames:requested.length*100,snapshot}));
}
main().catch(error=>{
 console.error("V7 FUTURES:",error instanceof Error?error.message:String(error));
 process.exitCode=1;
});